signature.code:
useField(resource, path): {
  value, error, isChanged, isTouched,
  onChange, onBlur, set, reset, validate
}

examples.code:
function CityField({ resource }) {
  const { value, error, onChange, onBlur } = useField(resource, 'addresses.0.city');
  return (
    <label>
      City
      <input
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error}
    </label>
  );
}
